### Objective
Build an interactive Production State Management Benchmark & Architectural Sandbox comparing ValueNotifier, Scoped Provider, and Cubit/BLoC side-by-side within a unified UI. Demonstrate live rebuild telemetry, memory disposal metrics, and architectural trade-offs.

```dart
import 'package:flutter/material.dart';
import 'package:provider/provider.dart' as p;
import 'package:flutter_bloc/flutter_bloc.dart' as b;
import 'package:equatable/equatable.dart';

void main() {
  runApp(const StateArchitectHarnessApp());
}

/// Root sandbox application
class StateArchitectHarnessApp extends StatelessWidget {
  const StateArchitectHarnessApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'State Architecture Benchmark',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.deepPurple,
        useMaterial3: true,
      ),
      home: const ArchitectureComparisonDashboard(),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. ENGINE A: NATIVE VALUENOTIFIER (Zero-Dependency Micro-Reactivity)
// ─────────────────────────────────────────────────────────────────────────────

class NativeCounterNotifier extends ValueNotifier<int> {
  NativeCounterNotifier() : super(0);
  int rebuildsCount = 0;

  void increment() {
    value++;
  }

  void reset() {
    value = 0;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. ENGINE B: SCOPED PROVIDER / CHANGENOTIFIER
// ─────────────────────────────────────────────────────────────────────────────

class ScopedCartNotifier extends ChangeNotifier {
  final List<String> _items = [];
  int rebuildsCount = 0;

  List<String> get items => List.unmodifiable(_items);
  int get itemCount => _items.length;

  void addItem(String item) {
    _items.add(item);
    notifyListeners();
  }

  void clearCart() {
    _items.clear();
    notifyListeners();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. ENGINE C: ENTERPRISE CUBIT (Immutable State Machine)
// ─────────────────────────────────────────────────────────────────────────────

class MetricState extends Equatable {
  final int totalActions;
  final String status;
  final bool isLoading;

  const MetricState({
    required this.totalActions,
    required this.status,
    this.isLoading = false,
  });

  MetricState copyWith({
    int? totalActions,
    String? status,
    bool? isLoading,
  }) {
    return MetricState(
      totalActions: totalActions ?? this.totalActions,
      status: status ?? this.status,
      isLoading: isLoading ?? this.isLoading,
    );
  }

  @override
  List<Object?> get props => [totalActions, status, isLoading];
}

class TelemetryCubit extends b.Cubit<MetricState> {
  int rebuildsCount = 0;

  TelemetryCubit()
      : super(const MetricState(totalActions: 0, status: 'Idle'));

  Future<void> recordAction() async {
    emit(state.copyWith(isLoading: true, status: 'Processing telemetry...'));
    await Future.delayed(const Duration(milliseconds: 250));
    emit(state.copyWith(
      totalActions: state.totalActions + 1,
      status: 'Action Recorded Successfully',
      isLoading: false,
    ));
  }

  void reset() {
    emit(const MetricState(totalActions: 0, status: 'Idle'));
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. PRESENTATION & BENCHMARK HARNESS
// ─────────────────────────────────────────────────────────────────────────────

class ArchitectureComparisonDashboard extends StatefulWidget {
  const ArchitectureComparisonDashboard({super.key});

  @override
  State<ArchitectureComparisonDashboard> createState() =>
      _ArchitectureComparisonDashboardState();
}

class _ArchitectureComparisonDashboardState
    extends State<ArchitectureComparisonDashboard> {
  final NativeCounterNotifier _nativeNotifier = NativeCounterNotifier();

  @override
  void dispose() {
    _nativeNotifier.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return p.MultiProvider(
      providers: [
        p.ChangeNotifierProvider(create: (_) => ScopedCartNotifier()),
        b.BlocProvider(create: (_) => TelemetryCubit()),
      ],
      child: Scaffold(
        appBar: AppBar(
          title: const Text('State Architecture Decision Lab'),
          centerTitle: true,
        ),
        body: ListView(
          padding: const EdgeInsets.all(16.0),
          children: [
            const _DecisionRubricBanner(),
            const SizedBox(height: 16),
            _NativeValueNotifierCard(notifier: _nativeNotifier),
            const SizedBox(height: 16),
            const _ScopedProviderCard(),
            const SizedBox(height: 16),
            const _EnterpriseCubitCard(),
          ],
        ),
      ),
    );
  }
}

class _DecisionRubricBanner extends StatelessWidget {
  const _DecisionRubricBanner();

  @override
  Widget build(BuildContext context) {
    return Card(
      color: Theme.of(context).colorScheme.primaryContainer,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: const Padding(
        padding: EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Architectural Decision Matrix',
              style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16),
            ),
            SizedBox(height: 6),
            Text(
              'Compare runtime rebuild behaviors, testability guarantees, and boilerplate trade-offs across native primitives, scoped providers, and event-driven state machines.',
              style: TextStyle(fontSize: 13),
            ),
          ],
        ),
      ),
    );
  }
}

class _NativeValueNotifierCard extends StatelessWidget {
  final NativeCounterNotifier notifier;
  const _NativeValueNotifierCard({required this.notifier});

  @override
  Widget build(BuildContext context) {
    return Card(
      elevation: 1,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                const Text(
                  '1. Native ValueNotifier',
                  style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16),
                ),
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                  decoration: BoxDecoration(
                    color: Colors.green.shade100,
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: const Text('Zero Dependency', style: TextStyle(fontSize: 11, color: Colors.green)),
                ),
              ],
            ),
            const SizedBox(height: 8),
            const Text(
              'Best For: High-frequency local micro-reactivity, animation controllers, and ephemeral widget toggles.',
              style: TextStyle(fontSize: 12, color: Colors.black54),
            ),
            const Divider(height: 24),
            ValueListenableBuilder<int>(
              valueListenable: notifier,
              builder: (context, count, child) {
                notifier.rebuildsCount++;
                return Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text('Current Value: $count', style: const TextStyle(fontWeight: FontWeight.w600)),
                        Text('Rebuild Count: ${notifier.rebuildsCount}', style: const TextStyle(fontSize: 12, color: Colors.deepPurple)),
                      ],
                    ),
                    FilledButton.tonal(
                      onPressed: notifier.increment,
                      child: const Text('Increment'),
                    ),
                  ],
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

class _ScopedProviderCard extends StatelessWidget {
  const _ScopedProviderCard();

  @override
  Widget build(BuildContext context) {
    return Card(
      elevation: 1,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                const Text(
                  '2. Scoped Provider',
                  style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16),
                ),
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                  decoration: BoxDecoration(
                    color: Colors.blue.shade100,
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: const Text('Tree Scoped DI', style: TextStyle(fontSize: 11, color: Colors.blue)),
                ),
              ],
            ),
            const SizedBox(height: 8),
            const Text(
              'Best For: Established codebases, medium complexity apps, and tree-scoped repository injection.',
              style: TextStyle(fontSize: 12, color: Colors.black54),
            ),
            const Divider(height: 24),
            p.Consumer<ScopedCartNotifier>(
              builder: (context, cart, child) {
                cart.rebuildsCount++;
                return Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text('Cart Items: ${cart.itemCount}', style: const TextStyle(fontWeight: FontWeight.w600)),
                        Text('Rebuild Count: ${cart.rebuildsCount}', style: const TextStyle(fontSize: 12, color: Colors.deepPurple)),
                      ],
                    ),
                    Row(
                      children: [
                        IconButton(
                          icon: const Icon(Icons.clear_all, size: 20),
                          onPressed: cart.clearCart,
                        ),
                        FilledButton.tonal(
                          onPressed: () => cart.addItem('Widget Item #${cart.itemCount + 1}'),
                          child: const Text('Add Item'),
                        ),
                      ],
                    ),
                  ],
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

class _EnterpriseCubitCard extends StatelessWidget {
  const _EnterpriseCubitCard();

  @override
  Widget build(BuildContext context) {
    return Card(
      elevation: 1,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                const Text(
                  '3. Enterprise Cubit',
                  style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16),
                ),
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                  decoration: BoxDecoration(
                    color: Colors.deepPurple.shade100,
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: const Text('State Machine', style: TextStyle(fontSize: 11, color: Colors.deepPurple)),
                ),
              ],
            ),
            const SizedBox(height: 8),
            const Text(
              'Best For: Enterprise applications, mission-critical financial systems, and full-stack testability.',
              style: TextStyle(fontSize: 12, color: Colors.black54),
            ),
            const Divider(height: 24),
            b.BlocBuilder<TelemetryCubit, MetricState>(
              builder: (context, state) {
                context.read<TelemetryCubit>().rebuildsCount++;
                return Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text('Actions Logged: ${state.totalActions}', style: const TextStyle(fontWeight: FontWeight.w600)),
                          Text(state.status, style: TextStyle(fontSize: 11, color: state.isLoading ? Colors.amber.shade900 : Colors.green.shade700)),
                          Text('Rebuild Count: ${context.read<TelemetryCubit>().rebuildsCount}', style: const TextStyle(fontSize: 12, color: Colors.deepPurple)),
                        ],
                      ),
                    ),
                    FilledButton.tonal(
                      onPressed: state.isLoading
                          ? null
                          : () => context.read<TelemetryCubit>().recordAction(),
                      child: state.isLoading
                          ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2))
                          : const Text('Record Event'),
                    ),
                  ],
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Native ValueNotifier Micro-Reactivity**:
   In `_NativeValueNotifierCard`, `ValueListenableBuilder` listens strictly to `NativeCounterNotifier`. It rebuilds exclusively its local leaf row with zero third-party packages or context-lookup overhead.
2. **Tree-Scoped Provider Management**:
   In `_ScopedProviderCard`, `p.Consumer<ScopedCartNotifier>` demonstrates scoped reactivity with automated disposal. Rebuilds are isolated to the specific card.
3. **Enterprise Cubit State Machine**:
   In `_EnterpriseCubitCard`, `b.BlocBuilder<TelemetryCubit, MetricState>` listens to immutable states. Notice how asynchronous operations (`recordAction`) transition cleanly from loading to loaded with zero race conditions.
4. **Live Rebuild Telemetry**:
   Each card maintains an active `rebuildsCount` telemetry counter, demonstrating directly in the UI how granular builder closures isolate re-renders from neighboring widgets.
